// MCP tools for batch 72 (3-Nov-2026): star map posters, fantasy maps, paper bag dielines.
// The pure cores come from src/tools_core72.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/
// draw-core-67d.js, starmap-data-72a.js, starmap-core-72a.js, fmap-core-72b.js, printpdf-core-72d.js, paperbag-core-72d.js) — one source of truth
// with the /tools/ pages star-map, fantasy-map-generator and paper-bag-template. Stateless: no D1/R2, no fetch.
// Star data: Yale Bright Star Catalogue 5th Revised Ed. (SAO TDC / NASA HEASARC); constellation lines: d3-celestial (BSD 3-Clause, (c) 2015 Olaf Frohn).
import { MGD72A, MGD72A_DATA as SD, MGD72B as FM, MGD72D } from "./tools_core72.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const OUT_CAP = 120 * 1024;
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const fin = (v) => Number.isFinite(num(v));
const r1 = (v) => Math.round(v * 10) / 10;
const r2 = (v) => Math.round(v * 100) / 100;
const S = MGD72A.star, BAG = MGD72D.bag;
const SIZES = S.SIZES.map((s) => s[0]), LAYOUTS = S.LAYOUTS.map((l) => l[0]), THEMES = Object.keys(S.THEMES);
const FSHAPES = FM.SHAPES.slice(), FSTYLES = Object.keys(FM.STYLES), FASPECT = Object.keys(FM.ASPECT);
const DIR16 = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"];
const UNIT = { mm: 1, cm: 10, in: 25.4 };

