        height: { type: "number", description: "Default 220 mm." }, hem: { type: "number", description: "Top fold-in (default 30 mm)." },
        bottom: { type: "number", description: "Front/back bottom flap (default 0.75 × gusset)." },
        handles: { type: "boolean", description: "Handle holes (default true)." },
        unit: { type: "string", enum: ["mm", "cm", "in"], description: "Default mm." },
