export const NEXT72 = {
  make_star_map: "Next step: open the star map link to pick the lettering, see the full-magnitude sky and download a print-ready PDF or 300 DPI PNG.",
  make_fantasy_map: "Next step: open the fantasy map link to rename places by clicking them, change fonts and export a high-resolution PNG or PDF.",
  make_paper_bag_template: "Next step: open the paper bag template link to add artwork to each panel and print it tiled on Letter or A4 with assembly steps.",
};

// ---- star map
const roundSky = (svg) => svg.replace(/ d="[^"]*"/g, (d) => d.replace(/(\d+\.\d)\d+/g, "$1")).replace(/ c([xy])="(-?\d+\.\d)\d*"/g, ' c$1="$2"');
const dir = (az) => DIR16[Math.round(az / 22.5) % 16];
function starMap(a) {
  if (typeof a.date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(a.date)) return err("date must be YYYY-MM-DD.");
  if (a.time !== undefined && !/^\d{1,2}:\d{2}$/.test(String(a.time))) return err("time must be HH:MM (local).");
  if (a.size !== undefined && !SIZES.includes(a.size)) return err("size must be one of: " + SIZES.join(", ") + ".");
  if (a.layout !== undefined && !LAYOUTS.includes(a.layout)) return err("layout must be one of: " + LAYOUTS.join(", ") + ".");
  if (a.theme !== undefined && !THEMES.includes(a.theme)) return err("theme must be one of: " + THEMES.join(", ") + ".");
  if (a.city === undefined && !(fin(a.lat) && fin(a.lon))) return err("Give a city (" + S.CITIES.slice(0, 6).map((c) => c[0].split(",")[0]).join(", ") + "…) or lat and lon.");
  if (a.lat !== undefined && !(fin(a.lat) && Math.abs(num(a.lat)) <= 90)) return err("lat must be -90..90.");
  if (a.lon !== undefined && !(fin(a.lon) && Math.abs(num(a.lon)) <= 180)) return err("lon must be -180..180.");
  if (a.utc_offset !== undefined && !(fin(a.utc_offset) && num(a.utc_offset) >= -12 && num(a.utc_offset) <= 14)) return err("utc_offset must be -12..14 hours.");
  if (a.tz !== undefined && S.tzOffset(String(a.tz), 2026, 1, 1, 12, 0) === null) return err("tz must be an IANA time zone such as Europe/Paris.");
  if (a.mag_limit !== undefined && !(fin(a.mag_limit) && num(a.mag_limit) >= 2 && num(a.mag_limit) <= 6)) return err("mag_limit must be 2-6.");
  const args = {
    date: a.date, time: a.time === undefined ? "21:00" : String(a.time), city: a.city !== undefined ? str(a.city, 60) : undefined, lat: fin(a.lat) ? num(a.lat) : undefined, lon: fin(a.lon) ? num(a.lon) : undefined,
    tz: a.tz, utc_offset: fin(a.utc_offset) ? num(a.utc_offset) : undefined, size: a.size, layout: a.layout, theme: a.theme,
    title: a.title !== undefined ? str(a.title, 80) : undefined, subtitle: a.subtitle !== undefined ? str(a.subtitle, 100) : undefined, place: a.place !== undefined ? str(a.place, 80) : undefined,
    mag_limit: fin(a.mag_limit) ? num(a.mag_limit) : 4.5, constellations: a.constellations, names: a.names, grid: a.grid, moon: a.moon,
  };
  if (args.city !== undefined && args.lat !== undefined) { delete args.city; }
  Object.keys(args).forEach((k) => args[k] === undefined && delete args[k]);
  let r;
  try { r = MGD72A.mcp.make_star_map(args); } catch (e) { return err(str(e && e.message, 300)); }
  const cty = args.city ? S.CITIES.find((x) => x[0].toLowerCase().startsWith(args.city.toLowerCase()) || x[0].toLowerCase().split(",")[0] === args.city.toLowerCase()) : null;
  const lat = cty ? cty[1] : args.lat, lon = cty ? cty[2] : args.lon, L = r.local_sidereal_time_hours * 15;
  const bright = Object.keys(SD.NAMES).map((hr) => { const s = SD.STARS.find((x) => x[0] === +hr); if (!s) return null; const h = S.eqToHor(s[1] / 100, s[2] / 100, lat, L); return { name: SD.NAMES[hr], mag: s[3] / 10, alt: r1(h.alt), az: r1(h.az), dir: dir(h.az) }; })
    .filter((x) => x && x.alt > 0).sort((p, q) => p.mag - q.mag).slice(0, 8);
  const svg = roundSky(r.svg), page = `${T}/star-map/`, off = r.utc_offset_hours, offs = "UTC" + (off < 0 ? "-" : "+") + Math.abs(off);
  const lst = r.local_sidereal_time_hours, lsts = Math.floor(lst) + "h " + String(Math.round((lst % 1) * 60) % 60).padStart(2, "0") + "m";
  const lines = [`**Star map: ${cty ? cty[0] : `${r2(lat)}°, ${r2(lon)}°`}, ${a.date} ${args.time || "21:00"} local (${offs}) = ${r.utc.slice(0, 16).replace("T", " ")} UTC; local sidereal time ${lsts}; ${r.visible_stars.toLocaleString("en-US")} stars to magnitude ${args.mag_limit} above the horizon.**`,
    `Moon: ${r.moon.name.toLowerCase()}, ${Math.round(r.moon.fraction * 100)}% lit, ${r.moon.alt > 0 ? `up at ${r.moon.alt}° ${dir(r.moon.az)}` : "below the horizon"}.`,
    bright.length ? "Brightest named stars up: " + bright.map((b) => `${b.name} ${b.alt}° ${b.dir}`).join(", ") + "." : "None of the brightest named stars is up."];
  if (r.warnings.length) lines.push("Note: " + r.warnings.join(" "));
  const sc = { place: cty ? cty[0] : null, lat, lon, utc: r.utc, utc_offset_hours: off, local_sidereal_time_hours: lst, visible_stars: r.visible_stars, mag_limit: args.mag_limit,
    constellation_segments: r.constellation_segments, moon: r.moon, bright_stars: bright, size: r.size, warnings: r.warnings, page };
  if (svg.length <= OUT_CAP) { lines.push(`Poster SVG (${r.size.name}, ${Math.round(svg.length / 1024)} KB, vector stars in mm; text uses system fonts):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push("The poster SVG is too large to return inline (lower mag_limit, or download it from the page)."); sc.svg_too_large = true; }
  lines.push("OFL lettering, magnitude 6 sky, print-ready PDF and 300 DPI PNG: " + page);
  return ok(lines.join("\n"), sc);
}

// ---- fantasy map
const roundD = (svg) => svg.replace(/ d="[^"]*"/g, (d) => d.replace(/(\d+)\.\d/g, "$1"));
function gridPattern(g, ink) {
  const s = g.flat, f = (v) => Math.round(v * 100) / 100;
  let tile, d;
  if (g.kind === "square") { tile = [s, s]; d = `M0 0H${f(s)}M0 0V${f(s)}`; }
  else { const r = s / Math.sqrt(3); tile = [s, 3 * r]; d = `M${f(s / 2)} 0L${f(s)} ${f(r / 2)}V${f(1.5 * r)}L${f(s / 2)} ${f(2 * r)}L0 ${f(1.5 * r)}V${f(r / 2)}ZM${f(s / 2)} ${f(2 * r)}V${f(3 * r)}`; }
  return `<defs><pattern id="mgd-fm-grid" width="${f(tile[0])}" height="${f(tile[1])}" patternUnits="userSpaceOnUse"><path d="${d}" fill="none" stroke="${ink}" stroke-width="0.8" stroke-opacity="0.35"/></pattern></defs>`;
}
function fantasy(a) {
  if (a.shape !== undefined && !FSHAPES.includes(a.shape)) return err("shape must be one of: " + FSHAPES.join(", ") + ".");
  if (a.style !== undefined && !FSTYLES.includes(a.style)) return err("style must be one of: " + FSTYLES.join(", ") + ".");
  if (a.aspect !== undefined && !FASPECT.includes(a.aspect)) return err("aspect must be one of: " + FASPECT.join(", ") + ".");
  if (a.grid !== undefined && !["none", "square", "hex"].includes(a.grid)) return err("grid must be none, square or hex.");
  if (a.detail !== undefined && !["low", "medium", "high"].includes(a.detail)) return err("detail must be low, medium or high.");
  if (a.land !== undefined && !(fin(a.land) && num(a.land) >= 10 && num(a.land) <= 80)) return err("land must be 10-80 (%).");
  for (const k of ["towns", "rivers"]) if (a[k] !== undefined && !(Number.isInteger(num(a[k])) && num(a[k]) >= 0 && num(a[k]) <= 15)) return err(k + " must be an integer 0-15.");
  if (a.across !== undefined && !(fin(a.across) && num(a.across) >= 1 && num(a.across) <= 20000)) return err("across must be 1-20000.");
  if (a.grid_cell !== undefined && !(fin(a.grid_cell) && num(a.grid_cell) > 0)) return err("grid_cell must be a positive distance.");
  const seed = a.seed !== undefined && String(a.seed).trim() ? str(a.seed, 40) : FM.randomSeed(Math.random);
  const across = fin(a.across) ? num(a.across) : 300, units = a.units === "km" ? "km" : "mi", cellU = fin(a.grid_cell) ? num(a.grid_cell) : 6, grid = a.grid || "none";
  const go = { seed, shape: a.shape, aspect: a.aspect, land: fin(a.land) ? num(a.land) : undefined, towns: a.towns === undefined ? undefined : num(a.towns), rivers: a.rivers === undefined ? undefined : num(a.rivers), roads: a.roads === false ? "no" : undefined };
  const steps = { high: [12, 16, 20], medium: [16, 20], low: [20] }[a.detail || "medium"];
  let m, dl, svg, cell;
  for (cell of steps) {
    m = FM.generate(Object.assign({}, go, { cell, density: 20 }));
    dl = FM.draw(m, { style: a.style, ripples: "no", title: a.title !== undefined ? str(a.title, 60) : undefined, across, units, showRoads: a.roads === false ? "no" : undefined });
    svg = roundD(FM.toSVG(dl, { title: (a.title && str(a.title, 60)) || m.names.region }));
    if (grid !== "none") {
      const g = FM.gridGeom({ grid, across, gridcell: cellU }, m), st = FM.STYLES[a.style || "parchment"] || FM.STYLES.parchment;
      const rect = `<rect x="0" y="0" width="${m.W}" height="${m.H}" fill="url(#mgd-fm-grid)"/>`;
      svg = svg.replace(/(<svg[^>]*>)/, "$1" + gridPattern(g, st.ink));
      svg = svg.includes('<g id="deco">') ? svg.replace('<g id="deco">', rect + '<g id="deco">') : svg.replace(/<\/svg>\s*$/, rect + "</svg>");
      m.__grid = g;
    }
    if (svg.length <= OUT_CAP) break;
  }
  const cnt = (t) => m.symbols.filter((s) => s.t === t).length, sb = FM.scaleBar(m, { across, units }), page = `${T}/fantasy-map-generator/`;
  const towns = m.towns.map((t) => ({ name: t.name, capital: !!t.capital, coastal: !!t.coastal, x: Math.round(t.x), y: Math.round(t.y) }));
  const g = m.__grid ? { kind: m.__grid.kind, cell_px: r2(m.__grid.flat), cols: m.__grid.cols, rows: m.__grid.rows, cell_distance: cellU, units } : null;
  const lines = [`**Fantasy map "${(a.title && str(a.title, 60)) || m.names.region}" (seed ${seed}, ${m.shape}, ${a.style || "parchment"}): ${m.W} × ${m.H} px, ${Math.round(m.landFraction * 100)}% land, ${across} ${units} across.**`,
    `Places: region ${m.names.region}, sea ${m.names.sea}, mountains ${m.names.range}; towns ${towns.map((t) => t.name + (t.capital ? " (capital)" : "")).join(", ") || "none"}.`,
    `Terrain: ${m.rivers.length} rivers, ${cnt("mountain")} mountains, ${cnt("hill")} hills, ${cnt("forest")} forest symbols, ${m.roads.length} roads. Scale bar ${sb.len} ${sb.units}.` + (g ? ` ${g.kind === "hex" ? "Hex" : "Square"} grid: ${cellU} ${units} per cell (${g.cols} × ${g.rows}).` : "")];
  const sc = { seed, shape: m.shape, style: a.style || "parchment", width: m.W, height: m.H, land_fraction: r2(m.landFraction), names: m.names, towns, rivers: m.rivers.length,
    symbols: { mountains: cnt("mountain"), hills: cnt("hill"), forests: cnt("forest") }, roads: m.roads.length, scale: { length: sb.len, units: sb.units, px: r1(sb.px) }, grid: g, detail_cell: cell, page };
  if (svg.length <= OUT_CAP) { lines.push(`SVG (${Math.round(svg.length / 1024)} KB${cell !== steps[0] ? ", coarser coastline to fit" : ""}; fonts load from jsDelivr, Georgia fallback):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push("The SVG is too large to return inline: open the page with the same seed to download it."); sc.svg_too_large = true; }
  lines.push(`Click-to-rename labels, fonts, full-detail PNG / PDF (seed ${seed}): ` + page);
  return ok(lines.join("\n"), sc);
}

// ---- paper bag
function paperBag(a) {
  const u = a.unit === undefined ? "mm" : a.unit;
  if (!UNIT[u]) return err("unit must be mm, cm or in.");
  const pr = a.preset !== undefined ? BAG.PRESETS.find((p) => p[0] === a.preset) : null;
  if (a.preset !== undefined && !pr) return err("preset must be one of: " + BAG.PRESETS.map((p) => p[0]).join(", ") + ".");
  for (const k of ["width", "gusset", "height", "hem", "bottom"]) if (a[k] !== undefined && !(fin(a[k]) && num(a[k]) >= 0)) return err(k + " must be a positive number.");
  const k = UNIT[u], mm = (key, d) => (fin(a[key]) ? num(a[key]) * k : d);
  const o = { width: mm("width", pr ? pr[2] : 160), gusset: mm("gusset", pr ? pr[3] : 80), height: mm("height", pr ? pr[4] : 220), hem: mm("hem", undefined), bottom: mm("bottom", undefined), handles: a.handles === false ? "none" : undefined };
  Object.keys(o).forEach((x) => o[x] === undefined && delete o[x]);
  const r = BAG.bag(o);
  if (!r.ok) return err(r.error + (u !== "mm" ? ` (you gave ${u}; limits are in mm)` : ""));
  const cv = (v) => r2(v / k), page = `${T}/paper-bag-template/`;
  const sheets = ["letter", "a4", "tabloid", "a3"].map((p) => { const g = r.gridFor(p); return { paper: g.label, sheets: g.n, orient: g.orient }; });
  const svg = r.svg({ title: "Paper bag template " + cv(r.width) + " x " + cv(r.gusset) + " x " + cv(r.height) + " " + u });
  const lines = [`**Paper bag ${cv(r.width)} × ${cv(r.gusset)} × ${cv(r.height)} ${u} (width × gusset × height): flat net ${cv(r.net.w)} × ${cv(r.net.h)} ${u}.**`,
    `Across: front ${cv(r.width)} | side ${cv(r.gusset)} | back ${cv(r.width)} | side ${cv(r.gusset)} | glue flap ${cv(r.flap)}. Down: top hem ${cv(r.hem)} | body ${cv(r.height)} | bottom flaps ${cv(r.bottom)} (side flaps ${cv(r.gusset / 2)}; front and back overlap ${cv(r.overlap)}).`,
    r.holes.length ? `Handle holes: ${r.holes.length / 2} through the hem and body, ${cv(r.holeSpacing)} ${u} apart on front and back.` : "No handle holes.",
    "Sheets (tiled, 10 mm overlap): " + sheets.map((s) => `${s.paper} ${s.sheets}`).join(", ") + "."];
  if (r.warnings.length) lines.push("Warnings: " + r.warnings.join(" "));
  const sc = { unit: u, width: cv(r.width), gusset: cv(r.gusset), height: cv(r.height), hem: cv(r.hem), glue_flap: cv(r.flap), bottom_flap: cv(r.bottom), side_flap: cv(r.gusset / 2), overlap: cv(r.overlap),
    net: { w: cv(r.net.w), h: cv(r.net.h) }, assembled: { w: cv(r.assembled.w), d: cv(r.assembled.d), h: cv(r.assembled.h) },
    panels: r.panels.map((p) => ({ id: p.id, x: cv(p.x), y: cv(p.y), w: cv(p.w), h: cv(p.h) })), holes: r.holes.map((h) => [cv(h[0]), cv(h[1])]), sheets, warnings: r.warnings, page };
  if (svg.length <= OUT_CAP) { lines.push(`True-size SVG (mm; solid = cut, dashed = fold):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push("The SVG is too large to return inline: download it from the page."); sc.svg_too_large = true; }
  lines.push("Panel artwork, tiled Letter / A4 PDF and folding steps: " + page);
  return ok(lines.join("\n"), sc);
}

const HANDLERS = { make_star_map: starMap, make_fantasy_map: fantasy, make_paper_bag_template: paperBag };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools72Tool(name) { return NAMES.has(name); }
export async function callTools72Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
